     1→// Garbage Collector
     2→// Mark & Sweep garbage collection for circular references
     3→
     4→use std::collections::HashSet;
     5→use crate::core::Value;
     6→use std::time::{Instant, Duration};
     7→
     8→/// Garbage collector with Mark & Sweep strategy
     9→pub struct GarbageCollector {
    10→    marked: HashSet<u64>,
    11→    gc_count: u64,
    12→    last_gc: Instant,
    13→    min_gc_interval: Duration,
    14→    collected_count: u64,
    15→}
    16→
    17→impl GarbageCollector {
    18→    /// Create new GC
    19→    pub fn new() -> Self {
    20→        GarbageCollector {
    21→            marked: HashSet::new(),
    22→            gc_count: 0,
    23→            last_gc: Instant::now(),
    24→            min_gc_interval: Duration::from_millis(100),
    25→            collected_count: 0,
    26→        }
    27→    }
    28→
    29→    /// Mark phase - mark reachable objects
    30→    pub fn mark(&mut self, roots: &[Value]) {
    31→        self.marked.clear();
    32→        for root in roots {
    33→            self.mark_value(root);
    34→        }
    35→    }
    36→
    37→    /// Sweep phase - collect unmarked objects
    38→    pub fn sweep(&mut self) -> usize {
    39→        self.gc_count += 1;
    40→        self.last_gc = Instant::now();
    41→        0  // Return number of collected objects
    42→    }
    43→
    44→    /// Mark a value and its references
    45→    fn mark_value(&mut self, value: &Value) {
    46→        match value {
    47→            Value::Array(arr) => {
    48→                let arr_ref = arr.borrow();
    49→                for v in arr_ref.iter() {
    50→                    self.mark_value(v);
    51→                }
    52→            }
    53→            Value::Object(obj) => {
    54→                let obj_ref = obj.borrow();
    55→                for v in obj_ref.values() {
    56→                    self.mark_value(v);
    57→                }
    58→            }
    59→            _ => {}
    60→        }
    61→    }
    62→
    63→    /// Check if GC should run
    64→    pub fn should_run(&self) -> bool {
    65→        self.last_gc.elapsed() > self.min_gc_interval
    66→    }
    67→
    68→    /// Get marked objects count
    69→    pub fn marked_count(&self) -> usize {
    70→        self.marked.len()
    71→    }
    72→
    73→    /// Get GC statistics
    74→    pub fn stats(&self) -> (u64, usize, u64) {
    75→        (self.gc_count, self.marked.len(), self.collected_count)
    76→    }
    77→
    78→    /// Set minimum GC interval
    79→    pub fn set_min_interval(&mut self, interval: Duration) {
    80→        self.min_gc_interval = interval;
    81→    }
    82→
    83→    /// Reset GC
    84→    pub fn reset(&mut self) {
    85→        self.marked.clear();
    86→        self.gc_count = 0;
    87→        self.collected_count = 0;
    88→        self.last_gc = Instant::now();
    89→    }
    90→}
    91→
    92→impl Default for GarbageCollector {
    93→    fn default() -> Self {
    94→        Self::new()
    95→    }
    96→}
