    11→    value: Value,
    12→    size: usize,
    13→    allocated_at: Instant,
    14→    ref_count: usize,
    15→}
    16→
    17→/// Memory allocator with GC support
    18→pub struct MemoryAllocator {
    19→    heap: HashMap<u64, AllocatedBlock>,
    20→    next_id: u64,
    21→    total_allocated: usize,
    22→    total_freed: usize,
    23→    gc_threshold: usize,  // Trigger GC at 5MB
    24→    allocation_count: u64,
    25→}
    26→
    27→impl MemoryAllocator {
    28→    /// Create new allocator
    29→    pub fn new() -> Self {
    30→        MemoryAllocator {
    31→            heap: HashMap::new(),
    32→            next_id: 1,
    33→            total_allocated: 0,
    34→            total_freed: 0,
    35→            gc_threshold: 5 * 1024 * 1024,  // 5MB
    36→            allocation_count: 0,
    37→        }
    38→    }
    39→
    40→    /// Allocate value on heap
    41→    pub fn allocate(&mut self, value: Value) -> u64 {
    42→        let id = self.next_id;
    43→        self.next_id += 1;
    44→
    45→        let size = self.estimate_size(&value);
    46→        self.total_allocated += size;
    47→        self.allocation_count += 1;
    48→
    49→        let block = AllocatedBlock {
    50→            value,
    51→            size,
    52→            allocated_at: Instant::now(),
    53→            ref_count: 1,
    54→        };
    55→
    56→        self.heap.insert(id, block);
    57→        id
    58→    }
    59→
    60→    /// Free allocated value
    61→    pub fn free(&mut self, id: u64) -> Option<Value> {
    62→        if let Some(block) = self.heap.remove(&id) {
    63→            self.total_freed += block.size;
    64→            Some(block.value)
    65→        } else {
    66→            None
    67→        }
    68→    }
